def bisect_left(a: Any, x: Any, lo: Any = 0, hi: Any = None) -> object {
    if (hi is None) {
        hi = len(a);
    }
    while (lo < hi) {
        mid = (lo + hi) // 2;
        if (a[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

