"""
    Used to calculate the ratio of the x and y axis of the image to the screen size.
    :param image_size: (x, y,) of image size.
    :param screen_size: (x, y,) of screen size.
    :return: (x, y,) as the ratio of the image size to the screen size.
    """
def get_cursor_ratio(image_size: tuple, screen_size: tuple) -> object {
    x_ratio = screen_size[0] / image_size[0];
    y_ratio = screen_size[1] / image_size[1];
    return (x_ratio, y_ratio);
}

"""
    Given a list of (word,tag) pairs, return a list of words which are tagged as nouns/verbs/etc
    The tagtype could be 'NN', 'JJ', 'VB', etc
    """
def get_tag_type(tagtype: Any, pairs: Any) -> object {
    return [
        w
        for (w, tag) in pairs
        if tag.startswith(tagtype)
    ];
}

"""Calculates BMI from specified height and mass

    BMI(kg/m2) = mass(kg) / height(m)2

    Arguments:
        mass {float} -- mass of the person in KG
        height {float} -- height of the person in meters

    Returns:
        bmi {float} -- Body Mass Index of the person from specified mass and height
    """
def calc_bmi(mass: Any, height: Any) -> object {
    bmi = mass / (height ** 2);
    bmi = round(bmi, 1);
    return bmi;
}

