"""Seconds to hours, minutes, seconds"""
def sec2hms(seconds: Any) -> object {
    (hours, seconds) = divmod(seconds, (60 ** 2));
    (minutes, seconds) = divmod(seconds, 60);
    return (int(hours), int(minutes), seconds);
}

